#!/usr/bin/env python3
"""Reproduce 48 deterministic DIMACS CNF fixtures using only Python's stdlib."""

from __future__ import annotations

import argparse
import itertools
import json
from dataclasses import dataclass
from pathlib import Path


ROOT = Path(__file__).resolve().parents[1]


@dataclass
class Fixture:
    name: str
    variables: int
    clauses: list[list[int]]
    expected: str
    family: str
    tier: str
    description: str
    parameters: str
    status_basis: str

    def dimacs(self) -> str:
        comments = [
            "Deterministically generated by tools/generate_structured_cnf.py.",
            self.description,
            f"Expected status: {self.expected}.",
            f"Parameters: {self.parameters}.",
            self.status_basis,
        ]
        lines = [f"c {comment}" for comment in comments]
        lines.append(f"p cnf {self.variables} {len(self.clauses)}")
        lines.extend(" ".join(map(str, clause + [0])) for clause in self.clauses)
        return "\n".join(lines) + "\n"

    def metadata(self) -> dict[str, str]:
        return {
            "path": f"structured/{self.name}.cnf",
            "expected": self.expected,
            "family": self.family,
            "tier": self.tier,
            "description": self.description,
            "origin": "generated",
            "generator": f"tools/generate_structured_cnf.py ({self.parameters})",
            "status_basis": self.status_basis,
        }


def at_most_one(variables: list[int]) -> list[list[int]]:
    return [[-left, -right] for left, right in itertools.combinations(variables, 2)]


def pigeonhole(pigeons: int, holes: int) -> Fixture:
    variable = lambda pigeon, hole: pigeon * holes + hole + 1
    clauses = []
    for pigeon in range(pigeons):
        row = [variable(pigeon, hole) for hole in range(holes)]
        clauses.append(row)
        clauses.extend(at_most_one(row))
    for hole in range(holes):
        clauses.extend(at_most_one([variable(pigeon, hole) for pigeon in range(pigeons)]))
    expected = "SAT" if pigeons <= holes else "UNSAT"
    basis = (
        "Witness: put pigeon i in hole i (indices start at zero)."
        if expected == "SAT"
        else "The pigeonhole principle forbids an injection from more pigeons into fewer holes."
    )
    return Fixture(
        f"pigeonhole-p{pigeons:02d}-h{holes:02d}-{expected.lower()}",
        pigeons * holes, clauses, expected, "pigeonhole",
        "stress" if expected == "UNSAT" and holes >= 5 else "smoke" if holes <= 2 else "regression",
        "Place each pigeon in exactly one hole, with at most one pigeon per hole.",
        f"pigeons={pigeons}, holes={holes}", basis,
    )


def coloring(kind: str, vertices: int, colors: int) -> Fixture:
    variable = lambda vertex, color: vertex * colors + color + 1
    edges = (
        [(vertex, (vertex + 1) % vertices) for vertex in range(vertices)]
        if kind == "cycle"
        else list(itertools.combinations(range(vertices), 2))
    )
    clauses = []
    for vertex in range(vertices):
        row = [variable(vertex, color) for color in range(colors)]
        clauses.append(row)
        clauses.extend(at_most_one(row))
    for left, right in edges:
        clauses.extend([[-variable(left, color), -variable(right, color)] for color in range(colors)])
    satisfiable = vertices % 2 == 0 if kind == "cycle" else vertices <= colors
    expected = "SAT" if satisfiable else "UNSAT"
    if kind == "cycle":
        basis = (
            "Witness: color vertex i with i modulo 2."
            if satisfiable else "An odd cycle cannot be colored with two colors."
        )
    else:
        basis = (
            "Witness: give every vertex its own color."
            if satisfiable else "A clique needs a distinct color for each of its vertices."
        )
    return Fixture(
        f"coloring-{kind}{vertices:03d}-k{colors}-{expected.lower()}",
        vertices * colors, clauses, expected, "graph-coloring",
        "regression" if vertices >= 100 or kind == "clique" else "smoke",
        f"Proper {colors}-coloring of a {vertices}-vertex {kind}.",
        f"graph={kind}, vertices={vertices}, colors={colors}", basis,
    )


def queen_witness(size: int) -> list[int] | None:
    """Return a deterministic row-to-column witness, or exhaust all choices."""
    positions: list[int] = []

    def search() -> list[int] | None:
        row = len(positions)
        if row == size:
            return positions.copy()
        for column in range(size):
            if any(
                other == column or abs(other - column) == row - previous
                for previous, other in enumerate(positions)
            ):
                continue
            positions.append(column)
            result = search()
            positions.pop()
            if result is not None:
                return result
        return None

    return search()


def queens(size: int) -> Fixture:
    variable = lambda row, column: row * size + column + 1
    clauses = []
    for row in range(size):
        variables = [variable(row, column) for column in range(size)]
        clauses.append(variables)
        clauses.extend(at_most_one(variables))
    for column in range(size):
        clauses.extend(at_most_one([variable(row, column) for row in range(size)]))
    for diagonal in range(-size + 1, size):
        clauses.extend(at_most_one([
            variable(row, column)
            for row in range(size) for column in range(size)
            if row - column == diagonal
        ]))
    for diagonal in range(2 * size - 1):
        clauses.extend(at_most_one([
            variable(row, column)
            for row in range(size) for column in range(size)
            if row + column == diagonal
        ]))
    witness = queen_witness(size)
    expected = "UNSAT" if size in (2, 3) else "SAT"
    assert (witness is not None) == (expected == "SAT")
    basis = (
        f"Witness: queen columns by row (zero-based) are {witness}."
        if witness is not None
        else "Boards of size 2 and 3 admit no nonattacking placement of one queen per row."
    )
    return Fixture(
        f"queens-n{size:02d}-{expected.lower()}", size * size, clauses,
        expected, "n-queens", "stress" if size >= 12 else "regression" if size >= 4 else "smoke",
        f"Place {size} nonattacking queens on a {size} by {size} board.",
        f"board_size={size}", basis,
    )


def graph_edges(kind: str, size: int) -> tuple[int, list[tuple[int, int]]]:
    edges: set[tuple[int, int]] = set()

    def edge(left: int, right: int) -> None:
        assert left != right
        edges.add((min(left, right), max(left, right)))

    if kind == "cycle":
        vertices = size
        for vertex in range(size):
            edge(vertex, (vertex + 1) % size)
    elif kind == "prism":
        vertices = 2 * size
        for vertex in range(size):
            edge(vertex, (vertex + 1) % size)
            edge(size + vertex, size + (vertex + 1) % size)
            edge(vertex, size + vertex)
    elif kind == "torus":
        vertices = size * size
        for row in range(size):
            for column in range(size):
                edge(row * size + column, row * size + (column + 1) % size)
                edge(row * size + column, ((row + 1) % size) * size + column)
    else:
        raise ValueError(kind)
    return vertices, sorted(edges)


def tseitin(kind: str, size: int, inconsistent: bool) -> Fixture:
    vertices, edges = graph_edges(kind, size)
    incident: list[list[int]] = [[] for _ in range(vertices)]
    # Derive even total charge from a concrete edge assignment; flip one charge
    # for the inconsistent partner. Every edge contributes at both endpoints.
    witness = [int(index % 3 == 0) for index in range(len(edges))]
    charges = [0] * vertices
    for index, (left, right) in enumerate(edges):
        incident[left].append(index + 1)
        incident[right].append(index + 1)
        charges[left] ^= witness[index]
        charges[right] ^= witness[index]
    if inconsistent:
        charges[0] ^= 1
    clauses = []
    for vertex, variables in enumerate(incident):
        # Each clause rules out exactly one incident assignment with wrong parity.
        for assignment in itertools.product((0, 1), repeat=len(variables)):
            if sum(assignment) % 2 != charges[vertex]:
                clauses.append([
                    -variable if value else variable
                    for variable, value in zip(variables, assignment)
                ])
    expected = "UNSAT" if inconsistent else "SAT"
    basis = (
        "XOR of all vertex equations is 0 = 1: every edge appears exactly twice, but total charge is odd."
        if inconsistent
        else "Witness: edge variable i is true exactly when (i - 1) modulo 3 equals zero. Charges are derived from this assignment."
    )
    return Fixture(
        f"tseitin-{kind}{size:02d}-{'odd' if inconsistent else 'even'}-{expected.lower()}",
        len(edges), clauses, expected, "tseitin-parity",
        "stress" if kind == "torus" and size >= 5 else "regression",
        f"Graph-based Tseitin parity constraints on a connected {kind} graph; total vertex charge is {'odd' if inconsistent else 'even'}.",
        f"graph={kind}, size={size}, inconsistent={str(inconsistent).lower()}", basis,
    )


def implication(length: int, inconsistent: bool) -> Fixture:
    clauses = [[1]] + [[-index, index + 1] for index in range(1, length)]
    if inconsistent:
        clauses.append([-length])
    expected = "UNSAT" if inconsistent else "SAT"
    basis = (
        "The first unit and successive implications force the final variable true, contradicting its negative unit."
        if inconsistent else "Witness: set every variable true."
    )
    return Fixture(
        f"implication-chain{length:04d}-{expected.lower()}", length, clauses,
        expected, "implication-chain", "regression" if length >= 32 else "smoke",
        "A positive unit propagates through a chain of implications" + (" to a contradictory final unit." if inconsistent else "."),
        f"length={length}, contradictory_final_unit={str(inconsistent).lower()}", basis,
    )


def fixtures() -> list[Fixture]:
    result = [pigeonhole(size, size) for size in (1, 2, 3, 4, 6, 8)]
    result += [pigeonhole(holes + 1, holes) for holes in (1, 2, 3, 5, 6, 7)]
    result += [coloring("cycle", size, 2) for size in (3, 4, 5, 6, 100, 101)]
    result += [coloring("clique", size, colors) for size, colors in ((3, 3), (4, 3), (4, 4), (5, 4))]
    result += [queens(size) for size in (1, 2, 3, 4, 5, 8, 10, 12)]
    result += [
        tseitin(kind, size, inconsistent)
        for kind, size in (("cycle", 9), ("prism", 5), ("torus", 3), ("torus", 4), ("torus", 5))
        for inconsistent in (False, True)
    ]
    result += [implication(length, inconsistent) for length in (1, 4, 32, 256) for inconsistent in (False, True)]
    assert len(result) == 48
    assert len({fixture.name for fixture in result}) == len(result)
    for fixture in result:
        assert all(0 < abs(literal) <= fixture.variables for clause in fixture.clauses for literal in clause)
    return sorted(result, key=lambda fixture: fixture.name)


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--output-dir", type=Path, default=ROOT / "tests" / "cnf" / "structured")
    parser.add_argument("--check", action="store_true", help="Verify committed files without changing them.")
    parser.add_argument("--metadata", type=Path, help="Optionally write metadata for integration into the corpus manifest.")
    args = parser.parse_args()
    generated = fixtures()
    if not args.check:
        args.output_dir.mkdir(parents=True, exist_ok=True)
    for fixture in generated:
        target = args.output_dir / f"{fixture.name}.cnf"
        content = fixture.dimacs().encode("ascii")
        if args.check:
            if not target.exists() or target.read_bytes() != content:
                raise SystemExit(f"Generated fixture differs: {target}")
        else:
            target.write_bytes(content)
    actual = {path.name for path in args.output_dir.glob("*.cnf")}
    expected = {f"{fixture.name}.cnf" for fixture in generated}
    if actual != expected:
        raise SystemExit(f"Unexpected CNF files in output directory: {sorted(actual - expected)}")
    if args.metadata:
        args.metadata.parent.mkdir(parents=True, exist_ok=True)
        args.metadata.write_text(json.dumps([fixture.metadata() for fixture in generated], indent=2) + "\n", encoding="utf-8")
    verb = "Verified" if args.check else "Generated"
    print(f"{verb} {len(generated)} structured DIMACS CNF fixtures in {args.output_dir}")


if __name__ == "__main__":
    main()
